-- PREPARADA: requer 001/002/003. Não atribui identidade a registros legados.
-- Usar somente após inventário/recuperação e validação em ambiente autorizado.
begin;
create table if not exists public.life_identities (
 id uuid primary key default gen_random_uuid(),
 profile_id uuid not null unique references public.game_characters(id) on delete restrict,
 world_id uuid not null, account_token text not null, life_token text not null,
 identity_status text not null check(identity_status='verified_source_life'),
 metrics jsonb not null default '{}', alive boolean, last_observed_at timestamptz not null,
 created_at timestamptz not null default now(),
 unique(world_id,account_token,life_token)
);
create table if not exists public.life_observations (
 id bigint generated always as identity primary key,
 life_id uuid not null references public.life_identities(id) on delete restrict,
 observed_at timestamptz not null, source_sha256 text not null,
 payload_digest text not null, metrics jsonb not null, alive boolean,
 unique(life_id,observed_at,source_sha256)
);
create table if not exists public.achievement_definitions (
 id text primary key, definition jsonb not null,
 check(definition->>'id'=id and definition->>'version'='1')
);
create table if not exists public.life_achievements (
 life_id uuid not null references public.life_identities(id) on delete restrict,
 achievement_id text not null references public.achievement_definitions(id) on delete restrict,
 observed_at timestamptz not null, recognized_at timestamptz not null default now(),
 occurred_at timestamptz, recognition_kind text not null default 'observed_counter'
   check(recognition_kind in ('observed_counter','official_archive')),
 evidence jsonb not null,
 primary key(life_id,achievement_id),
 check(occurred_at is null) -- Não há fonte de evento certificado nesta versão.
);
alter table public.life_identities enable row level security;
alter table public.life_observations enable row level security;
alter table public.achievement_definitions enable row level security;
alter table public.life_achievements enable row level security;
revoke all on public.life_identities,public.life_observations,public.achievement_definitions,public.life_achievements from public,anon,authenticated;

alter table public.player_statistics_current add column if not exists baseline_kills_vehicle integer;
alter table public.player_statistics_current add column if not exists source_kills_vehicle integer;
alter table public.player_statistics_current add column if not exists kills_vehicle integer;
alter table public.player_statistics_current add column if not exists baseline_kills_other integer;
alter table public.player_statistics_current add column if not exists source_kills_other integer;
alter table public.player_statistics_current add column if not exists kills_other integer;
-- Baseline próprio: o banco real antigo converte ausência de tempo em zero.
-- O contrato de vida nunca usa esse zero como uma leitura válida da temporada.
alter table public.player_statistics_current add column if not exists baseline_played_seconds bigint;
alter table public.player_statistics_current add column if not exists source_played_seconds bigint;
alter table public.player_stat_snapshots add column if not exists kills_vehicle integer;
alter table public.player_stat_snapshots add column if not exists kills_other integer;
alter table public.season_classification add column if not exists kills_vehicle integer;
alter table public.season_classification add column if not exists kills_other integer;

create or replace function public.freeze_extra_season_metrics_v1() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 select st.kills_vehicle,st.kills_other into new.kills_vehicle,new.kills_other
 from public.player_statistics_current st where st.season_id=new.season_id and st.character_id=new.profile_id;
 return new;
end; $$;
revoke all on function public.freeze_extra_season_metrics_v1() from public,anon,authenticated;
drop trigger if exists freeze_extra_season_metrics_v1 on public.season_classification;
create trigger freeze_extra_season_metrics_v1 before insert on public.season_classification
for each row execute function public.freeze_extra_season_metrics_v1();

create or replace function public.evaluate_life_achievements_v1(p_life_id uuid)
returns integer language plpgsql security definer set search_path='' as $$
declare l public.life_identities%rowtype; vals jsonb; def record; cond jsonb;
  v numeric; ok boolean; newly integer:=0; added integer; archive jsonb; keys text[];
begin
 select * into l from public.life_identities where id=p_life_id for update;
 if not found or l.identity_status<>'verified_source_life' then return 0; end if;
 select coalesce(jsonb_object_agg(e.key,e.value->'value'),'{}') into vals from jsonb_each(l.metrics) e;
 if l.alive is not null then vals:=vals||jsonb_build_object('alive',case when l.alive then 1 else 0 end); end if;
 keys:=array['kills_axe','kills_blunt','kills_small_blunt','kills_long_blade','kills_small_blade','kills_spear','kills_unarmed','kills_firearm','kills_vehicle','kills_other'];
 if vals ?& keys then
  vals:=vals||jsonb_build_object('categories_with_100_kills',(select count(*) from unnest(keys) k where (vals->>k)::numeric>=100));
 end if;
 select jsonb_strip_nulls(jsonb_build_object(
  'best_season_kills_total',max(a.kills_total), 'best_season_kills_firearm',max(a.kills_firearm),
  'best_season_kills_melee',max(a.kills_melee),'best_season_kills_vehicle',max(a.kills_vehicle),
  'seasons_completed_alive',count(*) filter(where a.alive_at_close and a.rank_position is not null),
  'official_wins',count(*) filter(where a.rank_position=1),
  'solo_official_wins',count(*) filter(where a.rank_position=1 and
    (select count(*) from public.season_classification peers where peers.season_id=a.season_id and peers.rank_position is not null)=1)
 )) into archive
 from public.season_classification a join public.season_results r on r.season_id=a.season_id
 where a.profile_id=l.profile_id and r.rules_version='winx-v1';
 vals:=vals||archive;
 for def in select id,definition from public.achievement_definitions loop
  ok:=true;
  for cond in select value from jsonb_array_elements(def.definition->'criteria') loop
   if not vals ? (cond->>'metric') then ok:=false; exit; end if;
   v:=(vals->>(cond->>'metric'))::numeric;
   if cond->>'op'='gte' then ok:=v>=(cond->>'value')::numeric;
   elsif cond->>'op'='eq' then
    ok:=v=(cond->>'value')::numeric and (cond->>'metric'='alive' or l.metrics->(cond->>'metric')->>'coverage'='complete_life');
   else ok:=false; end if;
   if ok is distinct from true then ok:=false; exit; end if;
   if exists(select 1 from jsonb_array_elements(def.definition->'criteria') z where z->>'op'='eq' and z->>'metric'<>'alive')
     and l.metrics->(cond->>'metric')->'observed_at' is distinct from to_jsonb(l.last_observed_at) then ok:=false; exit; end if;
  end loop;
  if ok then
   insert into public.life_achievements(life_id,achievement_id,observed_at,recognition_kind,evidence)
   values(l.id,def.id,l.last_observed_at,case when def.definition->'required_sources' ? 'official_archive' then 'official_archive' else 'observed_counter' end,
    jsonb_build_object('values',vals,'definition_version',1,'source_observed_at',l.last_observed_at))
   on conflict(life_id,achievement_id) do nothing;
   get diagnostics added=row_count; newly:=newly+added;
  end if;
 end loop;
 return newly;
end; $$;
revoke all on function public.evaluate_life_achievements_v1(uuid) from public,anon,authenticated;
grant execute on function public.evaluate_life_achievements_v1(uuid) to service_role;

create or replace function public.ingest_life_observation_v1(
 p_world_id uuid,p_account_token text,p_life_token text,p_character_name text,p_steam_username text,
 p_alive boolean,p_observed_at timestamptz,p_source_sha256 text,p_metrics jsonb
) returns uuid language plpgsql security definer set search_path='' as $$
declare profile uuid; l public.life_identities%rowtype; field record; expected text;
 clean jsonb:='{}'; n numeric; signature text; old_digest text; active uuid; vehicle integer; other_count integer; played bigint;
begin
 if p_world_id is null or p_account_token is null or p_account_token!~'^[0-9a-f]{64}$'
   or p_life_token is null or p_life_token!~'^[0-9a-f]{64}$' then raise exception 'verified source identity required'; end if;
 if p_observed_at is null or p_observed_at>now()+interval '1 minute' or p_source_sha256 is null or p_source_sha256!~'^[0-9a-f]{64}$'
   or p_metrics is null or jsonb_typeof(p_metrics)<>'object' or length(p_metrics::text)>20000 then raise exception 'invalid observation'; end if;
 for field in select * from jsonb_each(p_metrics) loop
  expected:=case when field.key in ('kills_total','kills_firearm','kills_melee','kills_vehicle','kills_axe','kills_blunt','kills_small_blunt','kills_long_blade','kills_small_blade','kills_spear','kills_unarmed','kills_other') then 'count'
    when field.key='played_seconds' then 'seconds' when field.key='survival_world_days' then 'world_days'
    when field.key in ('distance_total_m','distance_walked_m','distance_vehicle_m') then 'meters' else null end;
  if expected is null then raise exception 'unknown or backend-only metric'; end if;
  if jsonb_typeof(field.value)<>'object' or field.value->'validated' is distinct from 'true'::jsonb
    or field.value->>'scope' is distinct from 'life' or field.value->>'unit' is distinct from expected
    or jsonb_typeof(field.value->'value') is distinct from 'number' then raise exception 'unverified metric or unit'; end if;
  n:=(field.value->>'value')::numeric;
  if n<0 or n>31536000000 or expected='count' and (n<>trunc(n) or n>2000000000) then raise exception 'metric outside range'; end if;
  clean:=clean||jsonb_build_object(field.key,jsonb_build_object('value',n,'unit',expected,'scope','life','validated',true,'observed_at',p_observed_at,
    'coverage',case when field.value->>'coverage'='complete_life' then 'complete_life' else 'observed_lower_bound' end));
 end loop;
 signature:=md5(clean::text||coalesce(p_alive::text,'unknown')||coalesce(p_character_name,'')||coalesce(p_steam_username,''));
 select li.* into l from public.life_identities li where li.world_id=p_world_id and li.account_token=p_account_token and li.life_token=p_life_token;
 if found then
  select o.payload_digest into old_digest from public.life_observations o where o.life_id=l.id and o.observed_at=p_observed_at and o.source_sha256=p_source_sha256;
  if found then
   if old_digest<>signature then raise exception 'replayed observation has different content'; end if;
   return l.profile_id;
  end if;
 end if;
 profile:=public.ingest_player_observation('life-account:'||p_world_id||':'||p_account_token,
   'life-v1:'||p_world_id||':'||p_account_token||':'||p_life_token,p_character_name,p_alive,p_source_sha256,p_observed_at,
   (clean->'kills_total'->>'value')::integer,(clean->'kills_firearm'->>'value')::integer,
   (clean->'kills_melee'->>'value')::integer,(clean->'played_seconds'->>'value')::bigint,p_steam_username);
 insert into public.life_identities(profile_id,world_id,account_token,life_token,identity_status,last_observed_at)
 values(profile,p_world_id,p_account_token,p_life_token,'verified_source_life',p_observed_at)
 on conflict(world_id,account_token,life_token) do nothing;
 select * into l from public.life_identities li where li.profile_id=profile for update;
 select o.payload_digest into old_digest from public.life_observations o where o.life_id=l.id and o.observed_at=p_observed_at and o.source_sha256=p_source_sha256;
 if found then
  if old_digest<>signature then raise exception 'replayed observation has different content'; end if;
  return profile;
 end if;
 if l.last_observed_at>p_observed_at then raise exception 'out of order observation; no current data changed'; end if;
 if l.alive=false and p_alive is distinct from false then raise exception 'dead life cannot become alive or unknown; new source life token required'; end if;
 for field in select * from jsonb_each(clean) loop
  if l.metrics ? field.key and (l.metrics->field.key->>'value')::numeric>(field.value->>'value')::numeric then
   raise exception 'counter regression: identity/source requires investigation';
  end if;
 end loop;
 update public.life_identities set metrics=l.metrics||clean,alive=p_alive,last_observed_at=p_observed_at where id=l.id;
 insert into public.life_observations(life_id,observed_at,source_sha256,payload_digest,metrics,alive)
 values(l.id,p_observed_at,p_source_sha256,signature,clean,p_alive) on conflict do nothing;
 select s.id into active from public.ranking_seasons s where status='active';
 vehicle:=(clean->'kills_vehicle'->>'value')::integer; other_count:=(clean->'kills_other'->>'value')::integer; played:=(clean->'played_seconds'->>'value')::bigint;
 if active is not null then
  update public.player_statistics_current st set
   baseline_played_seconds=coalesce(st.baseline_played_seconds,played),source_played_seconds=coalesce(played,st.source_played_seconds),
   survival_seconds=case when played is null then null else played-coalesce(st.baseline_played_seconds,played) end,
   baseline_kills_vehicle=coalesce(st.baseline_kills_vehicle,vehicle),source_kills_vehicle=coalesce(vehicle,st.source_kills_vehicle),
   kills_vehicle=case when vehicle is null then st.kills_vehicle else vehicle-coalesce(st.baseline_kills_vehicle,vehicle) end,
   baseline_kills_other=coalesce(st.baseline_kills_other,other_count),source_kills_other=coalesce(other_count,st.source_kills_other),
   kills_other=case when other_count is null then st.kills_other else other_count-coalesce(st.baseline_kills_other,other_count) end
  where st.season_id=active and st.character_id=profile;
  update public.player_stat_snapshots sn set kills_vehicle=st.kills_vehicle,kills_other=st.kills_other,survival_seconds=st.survival_seconds
  from public.player_statistics_current st where st.season_id=active and st.character_id=profile
   and sn.season_id=active and sn.character_id=profile and sn.observed_at=p_observed_at and sn.source_blob_sha256=p_source_sha256;
 end if;
 perform public.evaluate_life_achievements_v1(l.id);
 return profile;
end; $$;
revoke all on function public.ingest_life_observation_v1(uuid,text,text,text,text,boolean,timestamptz,text,jsonb) from public,anon,authenticated;
grant execute on function public.ingest_life_observation_v1(uuid,text,text,text,text,boolean,timestamptz,text,jsonb) to service_role;

create or replace function public.get_public_life_achievements_v1(p_profile_id uuid)
returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('catalog_count',(select count(*) from public.achievement_definitions),
  'identity_verified',exists(select 1 from public.life_identities li where li.profile_id=p_profile_id),
  'last_observed_at',(select li.last_observed_at from public.life_identities li where li.profile_id=p_profile_id),
  'total_unlocked',(select count(*) from public.life_achievements a join public.life_identities li on li.id=a.life_id where li.profile_id=p_profile_id),
  'catalog',(select coalesce(jsonb_agg(d.definition order by d.id),'[]') from public.achievement_definitions d),
  'unlocks',(select coalesce(jsonb_agg(jsonb_build_object('achievement_id',a.achievement_id,'observed_at',a.observed_at,
    'recognized_at',a.recognized_at,'occurred_at',a.occurred_at,'recognition_kind',a.recognition_kind) order by a.recognized_at,a.achievement_id),'[]')
    from public.life_achievements a join public.life_identities li on li.id=a.life_id where li.profile_id=p_profile_id),
  'available_metrics',(select coalesce(jsonb_agg(k),'[]') from public.life_identities li cross join lateral jsonb_object_keys(li.metrics) k where li.profile_id=p_profile_id),
  'alive_known',exists(select 1 from public.life_identities li where li.profile_id=p_profile_id and li.alive is not null),
  'archive_available',exists(select 1 from public.life_identities li join public.season_classification a on a.profile_id=li.profile_id where li.profile_id=p_profile_id),
  'life_metrics',(select coalesce(jsonb_object_agg(e.key,jsonb_build_object('value',e.value->'value','unit',e.value->'unit')),'{}')
    from public.life_identities li cross join lateral jsonb_each(li.metrics) e where li.profile_id=p_profile_id),
  'life_history',(select coalesce(jsonb_agg(jsonb_build_object('observed_at',recent.observed_at,'alive',recent.alive,
    'kills_total',recent.metrics->'kills_total'->'value','survival_seconds',recent.metrics->'played_seconds'->'value') order by recent.observed_at,recent.id),'[]')
    from (select o.id,o.observed_at,o.metrics,o.alive from public.life_observations o join public.life_identities li on li.id=o.life_id
      where li.profile_id=p_profile_id order by o.observed_at desc,o.id desc limit 90) recent),
  'season_records',(select jsonb_strip_nulls(jsonb_build_object('best_season_kills_total',max(a.kills_total),
    'best_season_kills_firearm',max(a.kills_firearm),'best_season_kills_melee',max(a.kills_melee),'best_season_kills_vehicle',max(a.kills_vehicle)))
    from public.season_classification a join public.life_identities li on li.profile_id=a.profile_id
    join public.season_results r on r.season_id=a.season_id where li.profile_id=p_profile_id and r.rules_version='winx-v1'),
  'season_history',(select coalesce(jsonb_agg(jsonb_build_object('season_name',s.name,'outcome',r.outcome,
    'rank_position',a.rank_position,'kills_total',a.kills_total,'alive_at_close',a.alive_at_close,'closed_at',r.closed_at) order by r.closed_at desc,s.id),'[]')
    from public.season_classification a join public.life_identities li on li.profile_id=a.profile_id
    join public.season_results r on r.season_id=a.season_id join public.ranking_seasons s on s.id=a.season_id
    where li.profile_id=p_profile_id and r.rules_version='winx-v1'),
  'related_lives',(select coalesce(jsonb_agg(jsonb_build_object('profile_id',other.profile_id,'character_name',c.public_name,'alive',c.alive) order by other.created_at),'[]')
    from public.life_identities own join public.life_identities other on other.world_id=own.world_id and other.account_token=own.account_token and other.id<>own.id
    join public.game_characters c on c.id=other.profile_id where own.profile_id=p_profile_id),
  'complete_metrics',(select coalesce(jsonb_agg(e.key),'[]') from public.life_identities li cross join lateral jsonb_each(li.metrics) e
    where li.profile_id=p_profile_id and e.value->>'coverage'='complete_life' and e.value->'observed_at'=to_jsonb(li.last_observed_at)));
$$;
revoke all on function public.get_public_life_achievements_v1(uuid) from public;
grant execute on function public.get_public_life_achievements_v1(uuid) to anon,authenticated,service_role;
